mapper.select:
SELECT TNA.*,STAFF.REALNAME
FROM TBL_NBSJ_PROPOSAL TNA
LEFT JOIN TBL_STAFF STAFF ON STAFF.STAFFID = TNA.CREATESTAFFID

    1=1

        AND TNA.PROJECTID = #{tblNbsjProposalVo.projectId}


        AND TNA.PROCODE like concat(concat('%',#{tblNbsjProposalVo.procode}),'%')


        AND TNA.PRONAME like concat(concat('%',#{tblNbsjProposalVo.proname}),'%')


        AND to_char(TNA.CREATETIME,'yyyy-mm-dd') >= #{tblNbsjProposalVo.startDate}


        AND to_char(TNA.CREATETIME,'yyyy-mm-dd') <= #{tblNbsjProposalVo.endDate}


        ORDER BY TNA.PROID DESC
